--
-- Test data for the cross version tests. This data is a copy of the PEOPLE / ORDERS / PRODUCTS /
-- REVIEWS tables from the Metabase Sample Database (resources/sample-database.sqlite).
--
-- This script runs whenever the `postgres_data` volume doesn't exist on `docker compose up`.
--

CREATE DATABASE xv_sample_data OWNER metabase;

\connect xv_sample_data

CREATE TABLE "PRODUCTS" (
  "ID"         BIGINT PRIMARY KEY,
  "EAN"        CHAR(13),
  "TITLE"      VARCHAR(255),
  "CATEGORY"   VARCHAR(255),
  "VENDOR"     VARCHAR(255),
  "PRICE"      DOUBLE PRECISION,
  "RATING"     DOUBLE PRECISION,
  "CREATED_AT" TIMESTAMP
);

CREATE TABLE "PEOPLE" (
  "ID"         BIGINT PRIMARY KEY,
  "ADDRESS"    VARCHAR(255),
  "EMAIL"      VARCHAR(255),
  "PASSWORD"   VARCHAR(255),
  "NAME"       VARCHAR(255),
  "CITY"       VARCHAR(255),
  "LONGITUDE"  DOUBLE PRECISION,
  "STATE"      CHAR(2),
  "SOURCE"     VARCHAR(255),
  "BIRTH_DATE" DATE,
  "ZIP"        CHAR(5),
  "LATITUDE"   DOUBLE PRECISION,
  "CREATED_AT" TIMESTAMP
);

CREATE TABLE "ORDERS" (
  "ID"         BIGINT PRIMARY KEY,
  "USER_ID"    INTEGER REFERENCES "PEOPLE" ("ID"),
  "PRODUCT_ID" INTEGER REFERENCES "PRODUCTS" ("ID"),
  "SUBTOTAL"   DOUBLE PRECISION,
  "TAX"        DOUBLE PRECISION,
  "TOTAL"      DOUBLE PRECISION,
  "DISCOUNT"   DOUBLE PRECISION,
  "CREATED_AT" TIMESTAMP,
  "QUANTITY"   INTEGER
);

CREATE TABLE "REVIEWS" (
  "ID"         BIGINT PRIMARY KEY,
  "PRODUCT_ID" INTEGER REFERENCES "PRODUCTS" ("ID"),
  "REVIEWER"   VARCHAR(255),
  "RATING"     SMALLINT,
  "BODY"       VARCHAR(1024),
  "CREATED_AT" TIMESTAMP
);




